/**
 * Standardized outcome taxonomy for each discovered or interacted control.
 */
export type Outcome =
  | "PASS"
  | "FAIL"
  | "BLOCKED"
  | "FLAKY"
  | "OBSCURED"
  | "DEAD"
  | "RESTORE_FAILED"
  | "NOT_TESTED";

/**
 * Attribution source for observed errors.
 * Errors generated by the crawler's own safety blocks must never become FAIL.
 */
export type ErrorSource =
  | "application"
  | "third-party"
  | "background"
  | "crawler"
  | "unknown";

/**
 * Normalized, redacted error record captured during an observation window.
 */
export interface ErrorRecord {
  readonly code: string;
  readonly category: string;
  readonly message: string;
  readonly source: ErrorSource;
  readonly statusCode?: number;
  readonly origin?: string;
  readonly expected?: boolean;
  readonly blockedByCrawler?: boolean;
}

/**
 * Behavioural signal observed during or after an interaction window.
 */
export type SignalKind =
  | "url-change"
  | "navigation"
  | "dom-mutation"
  | "accessibility-event"
  | "state-change"
  | "network-request"
  | "network-blocked"
  | "dialog"
  | "popup"
  | "download"
  | "notification"
  | "visual-change"
  | "process-crash";

export interface SignalEvent {
  readonly kind: SignalKind;
  readonly targetKey?: string;
  readonly detail: string;
  readonly inClickedSubtree: boolean;
  readonly origin?: string;
  readonly error?: ErrorRecord;
}

/**
 * Multi-dimensional interaction observation separating execution, UI reaction,
 * correlation, expected-behaviour verification, and error attribution.
 */
export interface InteractionObservation {
  readonly interactionAttempted: boolean;
  readonly interactionSucceeded: boolean;
  readonly interactionDetected: boolean;
  readonly changeDetected: boolean;
  readonly changeCorrelated: boolean;
  readonly expectedBehaviourVerified: boolean;
  readonly attributedErrors: readonly ErrorRecord[];
  readonly attributionConfidence: "HIGH" | "MEDIUM" | "LOW";
  readonly signals: readonly SignalEvent[];
  readonly obscured?: boolean;
  readonly unstable?: boolean;
  readonly reason?: string;
}
